// ─────────────────────────────────────────────────────────────
// EDIT THESE BEFORE ACTIVATING
// ─────────────────────────────────────────────────────────────
const WEBHOOK_SECRET = 'CHANGE_ME_same_as_N8N_WEBHOOK_SECRET';
const SUPABASE_URL   = 'https://YOUR-PROJECT.supabase.co';
const SUPABASE_KEY   = 'YOUR_SERVICE_ROLE_KEY';

// Apify actors. Slugs verified against the Apify store; input schemas are
// pinned to what each actor's build actually declares.
const ACTOR_LINKEDIN = 'bebity~linkedin-jobs-scraper';
const ACTOR_INDEED   = 'misceres~indeed-scraper';

// How many listings to pull per source, per run. Apify bills by compute unit,
// and the user's own token pays — keep this modest.
const ROWS_PER_SOURCE = 50;

// Jobs sent to the model in one request. Scoring one job per call (the v1
// behaviour) meant N API calls per run; batching cuts that by ~15x.
const SCORE_BATCH_SIZE = 15;

// Model per provider. The user chooses the provider in onboarding; this maps
// that choice to a model id. Change any of these to trade cost for quality —
// it is the user's own key being billed.
const MODELS = {
  anthropic: 'claude-opus-5',
  openai:    'gpt-4o-mini',
  gemini:    'gemini-2.0-flash',
  groq:      'llama-3.3-70b-versatile'
};

return { json: {
  webhookSecret: WEBHOOK_SECRET,
  supabaseUrl:   SUPABASE_URL,
  supabaseKey:   SUPABASE_KEY,
  actorLinkedIn: ACTOR_LINKEDIN,
  actorIndeed:   ACTOR_INDEED,
  rowsPerSource: ROWS_PER_SOURCE,
  scoreBatchSize: SCORE_BATCH_SIZE,
  models: MODELS
} };

// Normalises the v2 payload from /api/v1/webhook/job-search.
//
// Changed since v1 and worth knowing: `workPreference` is now an ARRAY,
// `location` is `{ country: <ISO alpha-2>, worldwide: bool }` with no `city`,
// there is a new `jobTitles` array, and credentials arrive as `aiKeys` +
// `apifyKey` rather than a single `groqApiKey`.
const body   = $('Webhook Trigger').first().json.body || {};
const config = $('Set Config').first().json;

const countryCode = String(body.location?.country || '').toUpperCase();
const worldwide   = Boolean(body.location?.worldwide);

// Onboarding stores ISO codes; the scrapers want human names. Intl ships with
// Node, so no country table has to be maintained here.
let countryName = '';
if (countryCode) {
  try { countryName = new Intl.DisplayNames(['en'], { type: 'region' }).of(countryCode) || countryCode; }
  catch (e) { countryName = countryCode; }
}

const aiKeys = body.aiKeys || {};
// Prefer the provider the app nominated, but only if its key actually arrived.
const aiProvider = (body.aiProvider && aiKeys[body.aiProvider])
  ? body.aiProvider
  : Object.keys(aiKeys)[0];

if (!aiProvider)     throw new Error('No AI provider key in payload — cannot score.');
if (!body.apifyKey)  throw new Error('No Apify token in payload — cannot collect.');

// Field arrives as a slug ("software-engineering"); turn it back into words.
const fieldWords = String(body.field || '')
  .split('-').filter(Boolean)
  .map(w => w.charAt(0).toUpperCase() + w.slice(1))
  .join(' ');

const jobTitles = Array.isArray(body.jobTitles) ? body.jobTitles.filter(Boolean) : [];

return { json: {
  userId:         body.userId,
  workPreference: Array.isArray(body.workPreference) ? body.workPreference : [body.workPreference].filter(Boolean),
  worldwide,
  countryCode,
  countryName,
  field:          body.field || '',
  fieldWords:     fieldWords || 'Software Engineering',
  jobTitles,
  skills:         body.skills || [],
  experience:     body.experience || 0,
  jobType:        body.jobType || [],
  seniority:      body.seniority || 'mid',
  salary:         body.salary || { min: 0, max: 0, currency: 'USD' },
  aiProvider,
  aiApiKey:       aiKeys[aiProvider],
  aiModel:        config.models[aiProvider],
  apifyKey:       body.apifyKey,
  supabaseUrl:    config.supabaseUrl,
  supabaseKey:    config.supabaseKey,
  actorLinkedIn:  config.actorLinkedIn,
  actorIndeed:    config.actorIndeed,
  rowsPerSource:  config.rowsPerSource,
  scoreBatchSize: config.scoreBatchSize,
  timestamp:      new Date().toISOString()
} };

// Builds each actor's input from the user's preferences.
//
// Enum values below are taken from the actors' published input schemas, not
// guessed: LinkedIn workType 1/2/3 = On-Site/Remote/Hybrid, contractType
// F/P/C/T/I/V, experienceLevel 1..5, publishedAt r86400/r604800/r2592000.
const p = $input.item.json;

// Search term: a chosen job title beats the broad field — it is what the user
// actually asked for. Extra titles are dropped; both actors take one query.
const searchTerm = p.jobTitles[0] || p.fieldWords;

// Only constrain workplace type when the user picked exactly one. With several
// selected, filtering to one would hide the others; the model filters later.
const workTypeMap = { 'remote': '2', 'on-site': '1', 'hybrid': '3' };
const workType = p.workPreference.length === 1 ? (workTypeMap[p.workPreference[0]] || '') : '';

const contractMap = { 'full-time': 'F', 'part-time': 'P', 'contract': 'C', 'freelance': 'C' };
const contractType = p.jobType.length === 1 ? (contractMap[p.jobType[0]] || '') : '';

const experienceMap = { entry: '2', mid: '3', senior: '4', lead: '5' };
const experienceLevel = experienceMap[p.seniority] || '';

// `location` is required by the LinkedIn actor, so worldwide still needs a
// value — LinkedIn accepts "Worldwide" as a location in its own UI.
const linkedInLocation = p.worldwide ? 'Worldwide' : (p.countryName || 'Worldwide');

const linkedInInput = {
  title: searchTerm,
  location: linkedInLocation,
  rows: p.rowsPerSource,
  publishedAt: 'r604800',
  proxy: { useApifyProxy: true, apifyProxyGroups: ['RESIDENTIAL'] }
};
if (workType)        linkedInInput.workType = workType;
if (contractType)    linkedInInput.contractType = contractType;
if (experienceLevel) linkedInInput.experienceLevel = experienceLevel;

const indeedInput = {
  position: searchTerm,
  country: p.countryCode || 'US',
  location: p.worldwide ? '' : (p.countryName || ''),
  maxItemsPerSearch: p.rowsPerSource,
  parseCompanyDetails: false,
  saveOnlyUniqueItems: true,
  followApplyRedirects: false
};

console.log('Search term:', searchTerm, '| location:', linkedInLocation, '| workType:', workType || '(any)');

return { json: { ...p, linkedInInput, indeedInput } };

// Actor outputs are not a stable contract — field names differ between actors
// and change between builds. Rather than hard-code one shape, take the first
// key that exists from a list of likely names and log when nothing matches, so
// a rename shows up as an empty run rather than a silent crash.
function pick(obj, keys, fallback) {
  for (const k of keys) {
    const v = k.split('.').reduce((o, part) => (o == null ? o : o[part]), obj);
    if (v !== undefined && v !== null && v !== '') return v;
  }
  return fallback;
}
function clean(s) {
  return String(s == null ? '' : s).replace(/\s+/g, ' ').trim();
}
function rowsOf(input) {
  // The HTTP node hands back either the array itself or a wrapper object.
  const out = [];
  for (const item of input) {
    const j = item.json;
    if (Array.isArray(j)) out.push(...j);
    else if (Array.isArray(j.body)) out.push(...j.body);
    else if (Array.isArray(j.data)) out.push(...j.data);
    else if (j && typeof j === 'object' && Object.keys(j).length) out.push(j);
  }
  return out;
}

const rows = rowsOf($input.all());
if (!rows.length) { console.log('LinkedIn: 0 rows from Apify'); return []; }

const jobs = [];
const seen = new Set();
for (const r of rows) {
  const apply_url = clean(pick(r, ['jobUrl', 'url', 'link', 'applyUrl'], ''));
  const title     = clean(pick(r, ['title', 'jobTitle', 'position'], ''));
  if (!apply_url || !title || seen.has(apply_url)) continue;
  seen.add(apply_url);

  const location = clean(pick(r, ['location', 'jobLocation', 'place'], ''));
  const raw = (title + ' ' + location + ' ' + clean(pick(r, ['workType', 'workplaceType'], ''))).toLowerCase();
  let job_type = 'onsite';
  if (raw.includes('remote')) job_type = 'remote';
  else if (raw.includes('hybrid')) job_type = 'hybrid';

  jobs.push({
    title,
    company:          clean(pick(r, ['companyName', 'company', 'companyTitle'], 'Unknown')),
    location:         location || 'Not specified',
    job_type,
    description:      clean(pick(r, ['description', 'descriptionText', 'jobDescription'], '')).substring(0, 4000),
    apply_url,
    salary_text:      clean(pick(r, ['salary', 'salaryInfo', 'compensation'], '')) || null,
    posted_at_source: pick(r, ['postedAt', 'publishedAt', 'postedDate', 'datePosted'], null),
    source_key:       'apify_linkedin',
    external_id:      String(pick(r, ['id', 'jobId', 'urn'], apply_url))
  });
}
console.log('LinkedIn: ' + jobs.length + ' jobs from ' + rows.length + ' rows');
return jobs.map(j => ({ json: j }));

// Actor outputs are not a stable contract — field names differ between actors
// and change between builds. Rather than hard-code one shape, take the first
// key that exists from a list of likely names and log when nothing matches, so
// a rename shows up as an empty run rather than a silent crash.
function pick(obj, keys, fallback) {
  for (const k of keys) {
    const v = k.split('.').reduce((o, part) => (o == null ? o : o[part]), obj);
    if (v !== undefined && v !== null && v !== '') return v;
  }
  return fallback;
}
function clean(s) {
  return String(s == null ? '' : s).replace(/\s+/g, ' ').trim();
}
function rowsOf(input) {
  // The HTTP node hands back either the array itself or a wrapper object.
  const out = [];
  for (const item of input) {
    const j = item.json;
    if (Array.isArray(j)) out.push(...j);
    else if (Array.isArray(j.body)) out.push(...j.body);
    else if (Array.isArray(j.data)) out.push(...j.data);
    else if (j && typeof j === 'object' && Object.keys(j).length) out.push(j);
  }
  return out;
}

const rows = rowsOf($input.all());
if (!rows.length) { console.log('Indeed: 0 rows from Apify'); return []; }

const jobs = [];
const seen = new Set();
for (const r of rows) {
  const apply_url = clean(pick(r, ['url', 'jobUrl', 'link', 'externalApplyLink'], ''));
  const title     = clean(pick(r, ['positionName', 'title', 'jobTitle'], ''));
  if (!apply_url || !title || seen.has(apply_url)) continue;
  seen.add(apply_url);

  const location = clean(pick(r, ['location', 'jobLocation'], ''));
  const raw = (title + ' ' + location + ' ' + clean(pick(r, ['jobType', 'remoteWorkModel'], ''))).toLowerCase();
  let job_type = 'onsite';
  if (raw.includes('remote')) job_type = 'remote';
  else if (raw.includes('hybrid')) job_type = 'hybrid';

  jobs.push({
    title,
    company:          clean(pick(r, ['company', 'companyName'], 'Unknown')),
    location:         location || 'Not specified',
    job_type,
    description:      clean(pick(r, ['description', 'descriptionText', 'snippet'], '')).substring(0, 4000),
    apply_url,
    salary_text:      clean(pick(r, ['salary', 'salaryText'], '')) || null,
    posted_at_source: pick(r, ['postedAt', 'postingDateParsed', 'date'], null),
    source_key:       'apify_indeed',
    external_id:      String(pick(r, ['id', 'jobKey'], apply_url))
  });
}
console.log('Indeed: ' + jobs.length + ' jobs from ' + rows.length + ' rows');
return jobs.map(j => ({ json: j }));

// One listing often appears on both boards; keep the first and remember the URL
// list so the next node can ask Supabase which of them we already have.
const items = $input.all();
const seen = new Set();
const unique = [];
for (const item of items) {
  const url = item.json.apply_url;
  if (url && !seen.has(url)) { seen.add(url); unique.push(item.json); }
}
console.log('Dedupe: ' + unique.length + ' unique of ' + items.length);

// Both actors can legitimately return nothing (niche query, actor failure).
// Flow into the "no new jobs" response rather than throwing, which would fail
// the execution and leave the webhook hanging.
if (unique.length === 0) {
  return [{ json: { _skip: true, reason: 'No jobs returned by either source', jobs: [], urlListForDbCheck: '', totalCount: 0 } }];
}

const urlList = unique.map(j => '"' + String(j.apply_url).replace(/"/g, '\\"') + '"').join(',');
return { json: { jobs: unique, urlListForDbCheck: urlList, totalCount: unique.length } };

// Drop anything already stored, so the model is never paid to re-score a job.
const existingResponse = $input.first().json;
const dedupe = $('Dedupe Batch').first().json;
const prefs  = $('Extract Preferences').first().json;
const allJobs = dedupe.jobs || [];

if (allJobs.length === 0) {
  return [{ json: { _skip: true, reason: dedupe.reason || 'No jobs found' } }];
}

let existing = [];
if (Array.isArray(existingResponse)) existing = existingResponse;
else if (Array.isArray(existingResponse.body)) existing = existingResponse.body;
else {
  for (const key in existingResponse) {
    if (Array.isArray(existingResponse[key])) { existing = existingResponse[key]; break; }
  }
}

const existingUrls = new Set(existing.map(r => r.apply_url));
const newJobs = allJobs.filter(j => !existingUrls.has(j.apply_url));
console.log(allJobs.length + ' scraped, ' + existingUrls.size + ' already stored, ' + newJobs.length + ' new');

if (newJobs.length === 0) {
  return [{ json: { _skip: true, reason: 'No new jobs' } }];
}
return [{ json: { _skip: false, jobs: newJobs } }];

// v1 scored one job per API call. A 60-job run meant 60 requests, 60 round
// trips, and 60x the per-request prompt overhead. Batching sends ~15 jobs in
// one prompt and asks for one array back.
const prefs = $('Extract Preferences').first().json;
const jobs  = $input.first().json.jobs || [];
const size  = prefs.scoreBatchSize || 15;

const batches = [];
for (let i = 0; i < jobs.length; i += size) {
  batches.push({ json: { batchIndex: batches.length, jobs: jobs.slice(i, i + size) } });
}
console.log('Scoring ' + jobs.length + ' jobs in ' + batches.length + ' batch(es) of up to ' + size);
return batches;

// One node builds the URL, headers and body for whichever provider the user
// connected, so a single HTTP node can serve all four. Adding a provider means
// adding a case here — not another branch in the graph.
const prefs = $('Extract Preferences').first().json;
const batch = $input.item.json;

const profile = [
  'Field: ' + prefs.fieldWords,
  'Target titles: ' + (prefs.jobTitles.length ? prefs.jobTitles.join(', ') : '(any in field)'),
  'Skills: ' + (prefs.skills.length ? prefs.skills.join(', ') : '(not given)'),
  'Experience: ' + prefs.experience + ' years (' + prefs.seniority + ')',
  'Work preference: ' + (prefs.workPreference.join(', ') || 'any'),
  'Engagement: ' + (prefs.jobType.join(', ') || 'any'),
  'Location: ' + (prefs.worldwide ? 'Worldwide' : prefs.countryName),
  'Salary: ' + prefs.salary.min + '-' + prefs.salary.max + ' ' + prefs.salary.currency
].join('\n');

const listing = batch.jobs.map((j, i) => ({
  i,
  title: String(j.title || '').substring(0, 200),
  company: String(j.company || '').substring(0, 120),
  location: String(j.location || '').substring(0, 120),
  type: j.job_type,
  description: String(j.description || '').substring(0, 900)
}));

const instruction = 'Score each job against the candidate profile.\n\n'
  + 'CANDIDATE PROFILE:\n' + profile + '\n\n'
  + 'JOBS (JSON):\n' + JSON.stringify(listing) + '\n\n'
  + 'Return ONLY a JSON object of the form {"results":[...]} with one entry per job:\n'
  + '{"i": <the job index>, "score": <integer 0-100>, "tech_stack": ["lowercase","tech"],\n'
  + ' "seniority": "junior"|"mid"|"senior"|"lead"|null, "is_relevant": <boolean>,\n'
  + ' "match_reason": "<max 20 words>"}\n\n'
  + 'Scoring: 90-100 near-perfect; 70-89 good; 50-69 partial; 30-49 weak; 0-29 poor.\n'
  + 'Set is_relevant false only for a completely unrelated field or a recruiter spam post.\n'
  + 'Return an entry for every job, in the same order.';

const system = 'You are a job matching engine. Return only strict JSON. No markdown, no preamble.';
const model  = prefs.aiModel;
const key    = prefs.aiApiKey;

let aiUrl, aiHeaders, aiBody;

switch (prefs.aiProvider) {
  case 'anthropic':
    aiUrl = 'https://api.anthropic.com/v1/messages';
    aiHeaders = { 'x-api-key': key, 'anthropic-version': '2023-06-01', 'Content-Type': 'application/json' };
    // No `temperature` here on purpose: sampling parameters are rejected with a
    // 400 on current Opus/Sonnet models. Determinism comes from the prompt.
    // `effort: low` keeps a classification task from paying for deep thinking.
    aiBody = {
      model,
      max_tokens: 4000,
      system,
      output_config: { effort: 'low' },
      messages: [{ role: 'user', content: instruction }]
    };
    break;

  case 'openai':
    aiUrl = 'https://api.openai.com/v1/chat/completions';
    aiHeaders = { 'Authorization': 'Bearer ' + key, 'Content-Type': 'application/json' };
    aiBody = {
      model, temperature: 0, max_tokens: 4000,
      response_format: { type: 'json_object' },
      messages: [{ role: 'system', content: system }, { role: 'user', content: instruction }]
    };
    break;

  case 'gemini':
    aiUrl = 'https://generativelanguage.googleapis.com/v1beta/models/' + model + ':generateContent';
    aiHeaders = { 'x-goog-api-key': key, 'Content-Type': 'application/json' };
    aiBody = {
      systemInstruction: { parts: [{ text: system }] },
      contents: [{ role: 'user', parts: [{ text: instruction }] }],
      generationConfig: { temperature: 0, responseMimeType: 'application/json', maxOutputTokens: 4000 }
    };
    break;

  case 'groq':
  default:
    aiUrl = 'https://api.groq.com/openai/v1/chat/completions';
    aiHeaders = { 'Authorization': 'Bearer ' + key, 'Content-Type': 'application/json' };
    aiBody = {
      model, temperature: 0, max_tokens: 4000,
      response_format: { type: 'json_object' },
      messages: [{ role: 'system', content: system }, { role: 'user', content: instruction }]
    };
    break;
}

return { json: { batchIndex: batch.batchIndex, jobs: batch.jobs, aiUrl, aiHeaders, aiBody } };

// One parser for all four providers: pull the text payload out of whichever
// envelope came back, then read the same JSON contract from it.
const response = $input.item.json;
const request  = $('Build Scoring Request').item.json;
const prefs    = $('Extract Preferences').first().json;
const jobs     = request.jobs || [];

function extractText(r) {
  // Anthropic
  if (Array.isArray(r.content)) {
    return r.content.filter(b => b && b.type === 'text').map(b => b.text).join('');
  }
  // OpenAI / Groq
  if (r.choices && r.choices[0]) {
    return r.choices[0].message ? r.choices[0].message.content : r.choices[0].text;
  }
  // Gemini
  if (Array.isArray(r.candidates) && r.candidates[0]) {
    const parts = r.candidates[0].content && r.candidates[0].content.parts;
    if (Array.isArray(parts)) return parts.map(p => p.text || '').join('');
  }
  return '';
}

let results = [];
const text = extractText(response) || '';

if (!text) {
  console.log('Scoring failed for batch ' + request.batchIndex + ': ' + JSON.stringify(response).substring(0, 300));
} else {
  try {
    let parsed;
    try { parsed = JSON.parse(text); }
    catch (e) {
      // Some models still wrap JSON in prose or a code fence.
      const m = text.match(/\{[\s\S]*\}/);
      if (m) parsed = JSON.parse(m[0]);
    }
    if (parsed) results = parsed.results || parsed.jobs || (Array.isArray(parsed) ? parsed : []);
  } catch (e) {
    console.log('Parse error on batch ' + request.batchIndex + ': ' + e.message);
  }
}

const byIndex = new Map();
for (const r of results) {
  if (r && typeof r.i === 'number') byIndex.set(r.i, r);
}

// A scoring failure must not lose the job. Anything unscored is kept at a
// neutral 50 and flagged, so the run still produces matches.
return jobs.map((job, i) => {
  const r = byIndex.get(i) || {};
  const scored = byIndex.has(i);
  return { json: {
    ...job,
    tech_stack:  Array.isArray(r.tech_stack) ? r.tech_stack.map(t => String(t).toLowerCase()).slice(0, 8) : [],
    seniority:   ['junior', 'mid', 'senior', 'lead'].includes(r.seniority) ? r.seniority : null,
    is_relevant: r.is_relevant !== false,
    score:       typeof r.score === 'number' ? Math.min(100, Math.max(0, Math.round(r.score))) : 50,
    match_reason: r.match_reason || (scored ? '' : 'Not scored — provider error'),
    userId: prefs.userId
  } };
});

// v1 inserted one row per HTTP request. Everything relevant goes in one bulk
// POST instead, so a 60-job run is 1 request rather than 60.
const prefs = $('Extract Preferences').first().json;
const items = $input.all().map(i => i.json).filter(j => j.is_relevant !== false);

if (items.length === 0) {
  return [{ json: { _empty: true, rows: [], scored: [] } }];
}

// source_key → sources.id, matching the seed rows in supabase/schema.sql.
const SOURCE_IDS = { apify_linkedin: 4, apify_indeed: 5 };

const rows = items.map(j => ({
  title: j.title,
  company: j.company,
  location: j.location,
  job_type: j.job_type,
  description: j.description,
  apply_url: j.apply_url,
  salary_text: j.salary_text,
  posted_at_source: j.posted_at_source,
  tech_stack: j.tech_stack,
  seniority: j.seniority,
  is_relevant: j.is_relevant,
  source_id: SOURCE_IDS[j.source_key] || null,
  external_id: j.external_id
}));

console.log('Inserting ' + rows.length + ' relevant jobs of ' + $input.all().length + ' scored');
return [{ json: { _empty: false, rows, scored: items, supabaseUrl: prefs.supabaseUrl, supabaseKey: prefs.supabaseKey, userId: prefs.userId } }];

// Join the inserted job ids back to their scores by apply_url — Postgres does
// not guarantee the returned order matches the order sent.
const inserted = $input.first().json;
const src = $('Collect For Insert').first().json;

let rows = [];
if (Array.isArray(inserted)) rows = inserted;
else if (Array.isArray(inserted.body)) rows = inserted.body;

if (!rows.length) {
  console.log('No rows returned from insert — nothing to match. Response: ' + JSON.stringify(inserted).substring(0, 300));
  return [{ json: { _empty: true, matches: [] } }];
}

const scoreByUrl = new Map(src.scored.map(j => [j.apply_url, j.score]));
const matches = rows
  .filter(r => r.id && scoreByUrl.has(r.apply_url))
  .map(r => ({ user_id: src.userId, job_id: r.id, score: scoreByUrl.get(r.apply_url) }));

console.log('Upserting ' + matches.length + ' user/job matches');
return [{ json: { _empty: matches.length === 0, matches, supabaseUrl: src.supabaseUrl, supabaseKey: src.supabaseKey, count: matches.length } }];
